/// Keeps orders rows in memory, for tests and for trying the services without a database. Its copies share the rows.
#[derive(Clone, Default)]
pub struct MemoryOrderRepository {
    rows: Arc<Mutex<Vec<Order>>>,
    next_id: Arc<Mutex<i64>>,
}

impl MemoryOrderRepository {
    /// The rows reads see, by primary key.
    fn visible(&self) -> Vec<Order> {
        let mut rows: Vec<Order> = self.rows.lock().unwrap().iter().cloned().collect();
        rows.sort_by(|a, b| key_of(a).partial_cmp(&key_of(b)).unwrap_or(Ordering::Equal));
        rows
    }

    /// Keeps a row, in place of the one with its key.
    fn store(&self, entity: &Order) {
        let mut rows = self.rows.lock().unwrap();
        rows.retain(|row| key_of(row) != key_of(entity));
        rows.push(entity.clone());
    }
}

/// The key of a row, as a tuple of its key values.
fn key_of(row: &Order) -> (Option<i64>,) {
    (row.id,)
}

#[async_trait]
impl OrderRepository for MemoryOrderRepository {
    async fn find_by_id(&self, id: i64) -> Result<Option<Order>, DomainError> {
        Ok(self.visible().into_iter().find(|row| row.id.as_ref() == Some(&id)))
    }

    async fn list(&self, offset: u64, limit: u64) -> Result<Page<Order>, DomainError> {
        let rows = self.visible();
        let total = rows.len() as u64;
        Ok(Page { items: rows.into_iter().skip(offset as usize).take(limit as usize).collect(), total, offset, limit })
    }

    async fn list_by_customer_id(&self, customer_id: i64) -> Result<Vec<Order>, DomainError> {
        Ok(self.visible().into_iter().filter(|row| row.customer_id.as_ref() == Some(&customer_id)).collect())
    }

    async fn insert(&self, entity: Order) -> Result<Order, DomainError> {
        let mut entity = entity;
        entity.id = entity.id.or_else(|| {
            let mut next = self.next_id.lock().unwrap();
            *next += 1;
            Some(*next)
        });
        entity.placed_at = entity.placed_at.or_else(|| Some(chrono::Utc::now().fixed_offset()));
        self.store(&entity);
        Ok(entity)
    }

    async fn update(&self, entity: Order) -> Result<Order, DomainError> {
        self.store(&entity);
        Ok(entity)
    }

    async fn delete(&self, entity: &Order) -> Result<(), DomainError> {
        self.rows.lock().unwrap().retain(|row| key_of(row) != key_of(entity));
        Ok(())
    }
}

