    }

    async fn insert(&self, entity: Product) -> Result<Product, DomainError> {
        let mut entity = entity;
        entity.id = entity.id.or_else(|| {
            let mut next = self.next_id.lock().unwrap();
            *next += 1;
            Some(*next)
        });
        entity.version = entity.version.or_else(|| Some(1));
