        self.store(&entity);
        Ok(entity)
    }

    async fn delete(&self, entity: &Product) -> Result<(), DomainError> {
        self.rows.lock().unwrap().retain(|row| key_of(row) != key_of(entity));
        Ok(())
    }
}

