//! The service of the "products" table.

use crate::common::Page;
use crate::entities::product::Product;
use crate::entities::product_tag::ProductTag;
use crate::errors::{DomainError, FieldError};
use crate::unit_of_work::UnitOfWork;
use std::sync::Arc;

/// The values of a Product that change: fields left Absent keep their value; Patch::Set(None) empties one.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct ProductChanges {
    pub category_id: crate::common::Patch<Option<i64>>,
    pub name: crate::common::Patch<Option<String>>,
    pub price: crate::common::Patch<Option<rust_decimal::Decimal>>,
    pub status: crate::common::Patch<Option<String>>,
    pub version: crate::common::Patch<Option<i32>>,
    pub deleted_at: crate::common::Patch<Option<chrono::DateTime<chrono::FixedOffset>>>,
}

/// Operations on products. Each write runs in a transaction of its own.
pub struct ProductService {
    unit_of_work: Arc<dyn UnitOfWork>,
}

impl ProductService {
    pub fn new(unit_of_work: Arc<dyn UnitOfWork>) -> Self {
        Self { unit_of_work }
    }

    /// Stores a new Product after checking it.
    pub async fn create_product(&self, product: Product) -> Result<Product, DomainError> {
        let values = Values { category_id: product.category_id.map(Some), name: product.name.map(Some), price: product.price.map(Some), status: product.status.map(Some), version: product.version.map(Some), deleted_at: product.deleted_at.map(Some) };
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        check_values(uow, &values, None).await?;
        let mut entity = Product::default();
        apply_values(&mut entity, &values);
        let created = uow.products().insert(entity).await?;
        transaction.commit().await?;
        Ok(created)
    }

    /// The Product with this key; NotFound when there is none.
    pub async fn get_product(&self, id: i64) -> Result<Product, DomainError> {
        find(self.unit_of_work.as_ref(), id).await
    }

    /// A page of products, by primary key.
    pub async fn list_products(&self, offset: u64, limit: u64) -> Result<Page<Product>, DomainError> {
        self.unit_of_work.products().list(offset, limit).await
    }

    /// Changes the given values of a Product, read at version.
    pub async fn update_product(&self, id: i64, changes: ProductChanges, version: i32) -> Result<Product, DomainError> {
        let values = given(changes);
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        let mut current = find(uow, id).await?;
        if current.version != Some(version) {
            return Err(DomainError::conflict("Product", "was changed by someone else since it was read", &["version"]));
        }
        check_values(uow, &values, Some(&current)).await?;
        apply_values(&mut current, &values);
        current.version = Some(version + 1);
        let updated = uow.products().update(current).await?;
        transaction.commit().await?;
        Ok(updated)
    }

    /// Marks a Product as deleted (deleted_at); reads leave it out from then on.
    pub async fn delete_product(&self, id: i64, version: i32) -> Result<(), DomainError> {
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        let mut current = find(uow, id).await?;
        if current.version != Some(version) {
            return Err(DomainError::conflict("Product", "was changed by someone else since it was read", &["version"]));
        }
        if !uow.order_lines().list_by_product_id(current.id.expect("id is set")).await?.is_empty() {
            return Err(DomainError::conflict("Product", "rows of order_lines still point to it", &["order_lines"]));
        }
        current.deleted_at = Some(chrono::Utc::now().fixed_offset());
        uow.products().update(current).await?;
        transaction.commit().await?;
        Ok(())
    }

    /// The products with this category_id.
    pub async fn list_products_by_category_id(&self, category_id: i64) -> Result<Vec<Product>, DomainError> {
        self.unit_of_work.products().list_by_category_id(category_id).await
    }

    /// Links a Product and a Tag (product_tags).
    pub async fn add_tag(&self, product_id: i64, tag_id: i64) -> Result<(), DomainError> {
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        find(uow, product_id).await?;
        if uow.tags().find_by_id(tag_id).await?.is_none() {
            return Err(DomainError::not_found("Tag", tag_id));
        }
        if uow.product_tags().find_by_product_id_and_tag_id(product_id, tag_id).await?.is_some() {
            return Err(DomainError::conflict("Product", "is already linked to this Tag", &["tag_id"]));
        }
        uow.product_tags().insert(ProductTag { product_id: Some(product_id), tag_id: Some(tag_id) }).await?;
        transaction.commit().await?;
        Ok(())
    }

    /// Removes the link between a Product and a Tag (product_tags).
    pub async fn remove_tag(&self, product_id: i64, tag_id: i64) -> Result<(), DomainError> {
        let transaction = self.unit_of_work.begin().await?;
        let uow = transaction.as_ref();
        let link = uow.product_tags().find_by_product_id_and_tag_id(product_id, tag_id).await?.ok_or_else(|| DomainError::not_found("ProductTag", (product_id, tag_id)))?;
        uow.product_tags().delete(&link).await?;
        transaction.commit().await?;
        Ok(())
    }
}

/// The values a create or an update gives, by field: None when not given, Some(None) when given empty.
#[derive(Default)]
struct Values {
    category_id: Option<Option<i64>>,
    name: Option<Option<String>>,
    price: Option<Option<rust_decimal::Decimal>>,
    status: Option<Option<String>>,
    version: Option<Option<i32>>,
    deleted_at: Option<Option<chrono::DateTime<chrono::FixedOffset>>>,
}

/// Checks the values against the rules of the "products" table, and the rows they point to; ValidationFailed lists every problem.
async fn validate(uow: &dyn UnitOfWork, values: &Values, current: Option<&Product>) -> Result<(), DomainError> {
    let creating = current.is_none();
    let mut errors = Vec::new();
    match values.category_id.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.category_id.is_some() {
                errors.push(FieldError::new("category_id", "is required"));
            }
        }
        Some(_) => {}
    }
    match values.name.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.name.is_some() {
                errors.push(FieldError::new("name", "is required"));
            }
        }
        Some(value) => {
            if value.chars().count() > 100 {
                errors.push(FieldError::new("name", "is longer than 100 characters"));
            }
        }
    }
    match values.price.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.price.is_some() {
                errors.push(FieldError::new("price", "is required"));
            }
        }
        Some(value) => {
            if !(f64::try_from(*value).unwrap_or(f64::NAN) >= 0.0) {
                errors.push(FieldError::new("price", "must be >= 0"));
            }
        }
    }
    match values.status.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if creating || values.status.is_some() {
                errors.push(FieldError::new("status", "is required"));
            }
        }
        Some(value) => {
            if value.chars().count() > 10 {
                errors.push(FieldError::new("status", "is longer than 10 characters"));
            }
        }
    }
    match values.version.as_ref().and_then(|value| value.as_ref()) {
        None => {
            if !creating && values.version.is_some() {
                errors.push(FieldError::new("version", "cannot be empty"));
            }
        }
        Some(_) => {}
    }
    {
        let category_id = values.category_id.clone().unwrap_or_else(|| current.and_then(|current| current.category_id));
        if let Some(category_id) = category_id {
            if uow.categories().find_by_id(category_id).await?.is_none() {
                errors.push(FieldError::new("category_id", "no Category has this key"));
            }
        }
    }
    if errors.is_empty() {
        Ok(())
    } else {
        Err(DomainError::ValidationFailed { entity: "Product".to_string(), errors })
    }
}

/// Every check before a write: the values, the rows they point to, the unique values.
async fn check_values(uow: &dyn UnitOfWork, values: &Values, current: Option<&Product>) -> Result<(), DomainError> {
    validate(uow, values, current).await?;
    Ok(())
}

/// Sets the given values on the entity.
fn apply_values(entity: &mut Product, values: &Values) {
    if let Some(value) = &values.category_id {
        entity.category_id = *value;
    }
    if let Some(value) = &values.name {
        entity.name = value.clone();
    }
    if let Some(value) = &values.price {
        entity.price = *value;
    }
    if let Some(value) = &values.status {
        entity.status = value.clone();
    }
    if let Some(value) = &values.version {
        entity.version = *value;
    }
    if let Some(value) = &values.deleted_at {
        entity.deleted_at = *value;
    }
}

/// The values an update gives, by field.
fn given(changes: ProductChanges) -> Values {
    Values { category_id: changes.category_id.given(), name: changes.name.given(), price: changes.price.given(), status: changes.status.given(), version: changes.version.given(), deleted_at: changes.deleted_at.given() }
}

/// The Product with this key; NotFound when there is none.
async fn find(uow: &dyn UnitOfWork, id: i64) -> Result<Product, DomainError> {
    uow.products().find_by_id(id).await?.ok_or_else(|| DomainError::not_found("Product", id))
}

