//! The service of the "tags" table, on the in-memory repositories.

use rust_sql_sqlite_defaults::common::Patch;
use rust_sql_sqlite_defaults::errors::DomainError;
use rust_sql_sqlite_defaults::services::tag::{TagChanges, TagService};
use rust_sql_sqlite_defaults::unit_of_work::MemoryUnitOfWork;
use std::sync::Arc;
use super::factories;

#[tokio::test]
async fn creates_a_valid_row() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = TagService::new(uow.clone());
    let row = factories::new_tag(1);
    let created = service.create_tag(row).await.expect("a create");
    let found = service.get_tag(created.id.expect("id is set")).await.expect("a read");
    assert_eq!(created.id, found.id);
}

#[tokio::test]
async fn refuses_a_missing_value() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = TagService::new(uow.clone());
    let mut row = factories::new_tag(1);
    row.label = None;
    let error = service.create_tag(row).await.expect_err("a refusal");
    let DomainError::ValidationFailed { errors, .. } = &error else { panic!("{error}") };
    assert_eq!(vec!["label"], errors.iter().map(|error| error.field.as_str()).collect::<Vec<_>>());
}

#[tokio::test]
async fn says_when_a_row_is_missing() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = TagService::new(uow.clone());
    assert!(matches!(service.get_tag(999999).await, Err(DomainError::NotFound { .. })));
}

#[tokio::test]
async fn changes_a_row() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = TagService::new(uow.clone());
    let row = factories::new_tag(1);
    let created = service.create_tag(row.clone()).await.expect("a create");
    let updated = service.update_tag(created.id.expect("id is set"), TagChanges { label: Patch::Set(Some("changed".to_string())), ..Default::default() }).await.expect("an update");
    assert_eq!(updated.label, Some("changed".to_string()));
}

#[tokio::test]
async fn deletes_a_row() {
    let uow = Arc::new(MemoryUnitOfWork::default());
    let service = TagService::new(uow.clone());
    let row = factories::new_tag(1);
    let created = service.create_tag(row).await.expect("a create");
    service.delete_tag(created.id.expect("id is set")).await.expect("a delete");
    assert!(matches!(service.get_tag(created.id.expect("id is set")).await, Err(DomainError::NotFound { .. })));
}
